mapper.insert:
/* spcReg.savApiSpc */
SELECT CURRVAL('koa_tb_api_spc_api_spc_no_seq')
INSERT INTO KOA_TB_API_SPC ( API_SPC_NO ,API_SPC_ID ,VER ,API_NM ,API_DESC ,AUT_ID ,SYS_ID ,HOST ,BAS_PATH ,YAML_FILE_PATH ,YAML_FILE_NM ,REG_STTUS_CD ,REG_DT ,REGR ,AMD_DT ,AMDR ,DEL_YN ,SHOW_YN ,API_CLASS ,API_SCHEMA ,BSTGW_YN ,API_VERI_BASEURL ) SELECT NID.ID ,CONCAT('GRP-', NID.ID) ,#{ver} ,#{apiNm} ,#{apiDesc} ,#{autId}::integer ,#{sysId} ,#{host} ,#{basPath} ,'/spcreg' ,CONCAT(#{apiNm}::text, '.yaml') ,'APIREG1020' ,NOW() ,#{regr} ,NOW() ,#{amdr} ,'N' ,'N' ,#{apiClass} ,#{apiSchema} ,#{bstgwYn} ,#{apiVeriBaseurl} FROM ( SELECT NEXTVAL('koa_tb_api_spc_api_spc_no_seq') AS ID ) NID

mapper.update:
/* spcReg.updApiSpc */
UPDATE KOA_TB_API_SPC
SET VER = #{ver}
  ,API_NM = #{apiNm}
  ,API_DESC = #{apiDesc}
  ,AUT_ID = #{autId}::integer
  ,SYS_ID = #{sysId}
  ,HOST = #{host}
  ,BAS_PATH = #{basPath}
  ,API_CLASS = #{apiClass}
  ,API_SCHEMA = #{apiSchema}
  ,BSTGW_YN = #{bstgwYn}
  ,API_VERI_BASEURL = #{apiVeriBaseurl}
  ,AMD_DT = NOW()
  ,AMDR = #{amdr}
WHERE API_SPC_NO = #{apiSpcNo}::integer
  AND DEL_YN = 'N'
